int a[5] = {3, 8, 4, 2, 9};
// a         -> dia chi cua a[0]
// a + i     -> dia chi cua a[i]
// *(a + i)  -> gia tri cua a[i]

for (int i = 0; i < 5; i++) {
    cout << *(a + i) << ' ';   // 3 8 4 2 9
}

int a[5] = {3, 8, 4, 2, 9};
int *ptr = &a[0];

++ptr;      // ptr tro toi a[1], gia tri 8
ptr += 2;   // ptr tro toi a[3], gia tri 2
--ptr;      // ptr tro toi a[2], gia tri 4
